struct MansionDriver:Driver{
 using Driver::Driver;
 void press(InputAction a=InputAction::Confirm){tick(key(a));tick();}
 void select(int id){const auto v=game.menuView();const auto it=std::find_if(v.rows.begin(),v.rows.end(),[&](const auto& row){return row.id==id;});need(it!=v.rows.end(),"Missing public menu row");const int n=int(it-v.rows.begin());for(int j=0;j<int(v.rows.size())&&game.menuView().selection!=n;++j){press(v.columns==2?InputAction::Right:InputAction::Down);}need(game.menuView().selection==n,"Public menu selection failed");press();}
 void equip(int id){if(game.session().equipped(1)==id){return;}press(InputAction::Cancel);need(game.mode()==ApplicationMode::Equipment,"Public equip menu absent");select(2);select(1);select(id);press(InputAction::Cancel);press(InputAction::Cancel);need(game.session().equipped(1)==id,"Public DE equip failed");}
 void item(int id){press(InputAction::Cancel);need(game.mode()==ApplicationMode::Equipment,"Public medicine menu absent");select(0);select(id);if(game.mode()==ApplicationMode::Equipment&&game.menuView().page==MenuPage::Target){press();}for(int n=0;n<3&&game.mode()==ApplicationMode::Equipment;++n){press(InputAction::Cancel);}settle();}
 void choices(int choice){std::uint64_t request{};int first{};for(int n=0;n<20000;++n){if(game.foreground()==ForegroundKind::None&&!game.dialogue().active()&&!game.world().player().motion.moving()){return;}InputFrame in=n%8==0?key():InputFrame{};auto v=game.inputPromptView();if(v.cursor){if(request!=v.request){request=v.request;first=v.cursor->line;}in=key(v.cursor->line==first+choice?InputAction::Confirm:InputAction::Down);}tick(in);}throw std::runtime_error("Lock choice did not finish");}
 void unlock(TilePosition tile,Direction direction,int choice=0){walk(tile);move(direction);tick(key());choices(choice);}
};
void battle(MansionDriver& run){
 int shots=0,fired=0;for(int n=0;n<20000;++n){auto& game=run.game;auto& s=game.session();need(s.hp()>0,"Natural04 battle died");const int rounds=s.magazine(s.equipped(1));std::vector<std::string> alive;for(const auto& [id,e]:game.content().enemies){if(e.map==game.mapId()&&!s.flag(e.deadFlag)){alive.push_back(id);}}if(alive.empty()){break;}InputFrame in;
 if(game.foreground()!=ForegroundKind::None||game.dialogue().active()){if(n%8==0){in=key();}}
 else if(!game.raised()){in=key(InputAction::Weapon);}
 else{const auto p=game.world().player().motion.tile();auto id=*std::min_element(alive.begin(),alive.end(),[&](const auto& a,const auto& b){auto x=findCharacter(game.world(),a).motion.tile(),y=findCharacter(game.world(),b).motion.tile();return std::abs(x.x-p.x)+std::abs(x.y-p.y)<std::abs(y.x-p.x)+std::abs(y.y-p.y);});const auto t=findCharacter(game.world(),id).motion.tile();const int dx=t.x-p.x,dy=t.y-p.y;const Direction face=std::abs(dx)>std::abs(dy)?(dx>0?Direction::Right:Direction::Left):(dy>0?Direction::Down:Direction::Up);
 if(n%200==0){std::cout<<"FIGHT map="<<game.mapId()<<" n="<<n<<" p="<<p.x<<","<<p.y<<" target="<<id<<"/"<<t.x<<","<<t.y<<" HP="<<s.hp()<<" ammo="<<s.magazine(s.equipped(1))<<" state="<<s.variable(game.content().enemies.at(id).rules.at("state_variable"))<<" dmg="<<s.variable(game.content().enemies.at(id).rules.at("damage_variable"))<<'\n';}
 if((dx&&dy)||std::abs(dx)+std::abs(dy)>4){for(Direction side:{Direction::Down,Direction::Up,Direction::Right,Direction::Left}){const auto step=next(game.world(),adjacentTile(t,side));if(step){in.movement=step;break;}}}
 else if(game.world().player().motion.facing()!=face){in.buttons[int(InputAction::Weapon)].held=true;in.movement=face;}else if(n%6==0){in=key(InputAction::Attack);++shots;}}
 run.tick(in);fired+=std::max(0,rounds-run.game.session().magazine(run.game.session().equipped(1)));if(n==19999){throw std::runtime_error("Natural04 battle stalled");}
 }
 for(int attempt=0;attempt<3&&run.game.raised();++attempt){for(int n=0;n<24;++n){InputFrame in;in.buttons[int(InputAction::Weapon)].held=true;run.tick(in);}for(int n=0;n<60;++n){run.tick();}run.settle();}need(!run.game.raised(),"Public Shift gesture failed to lower after battle");run.settle();if(run.game.session().hp()<80&&run.game.session().count(5)>0){run.item(5);}std::cout<<"REAL04 map="<<run.game.mapId()<<" attackPresses="<<shots<<" roundsFired="<<fired<<" HP="<<run.game.session().hp()<<" count="<<run.game.session().variable(35)<<'\n';
}
